  "returncode": 0,
  "output_head": "<% content_for :title, "Quizzy · #{@quiz.title}" %>

<% active_count = @questions.count(&:active?) %>
<% total_count = @questions.size %>

<div data-controller="question-active">
  <div class="breadcrumbs">
    <%= link_to "← All quizzes", moderate_root_path %>
  </div>

  <div class="page-head">
    <div>
      <h1><%= @quiz.title %></h1>
      <div class="meta mt-2">
        <span data-question-active-target="summary"><%= active_count %> of <%= pluralize(total_count, "question") %> active</span>
        ·
        <%= link_to "Settings", edit_moderate_quiz_path(@quiz) %>
      </div>
    </div>
    <div class="buttons">
      <%= link_to "Preview", moderate_quiz_preview_path(@quiz), class: "btn btn--ghost" %>
    </div>
  </div>

  <section class="section mt-0">
    <div class="section-head">
      <h2>Questions</h2>
      <%= link_to "Add question", new_moderate_quiz_question_path(@quiz), class: "btn" %>
    </div>

    <% if @questions.any? %>
      <ol class="question-list" data-question-active-target="list">
        <% active_number = 0 %>
        <% @questions.each_with_index do |question, index| %>
          <% active_number += 1 if question.active? %>
          <li class="card question-item <%= 'question-item--inactive' unless question.active? %>"
              data-question-active-target="item">
            <div class="question-item__num" data-question-active-target="number">
              <%= question.active? ? active_number : "—" %>
            </div>

            <div>
              <div class="question-item__body"><%= question.body %></div>
              <ul class="question-item__options">
                <% question.options.each_with_index do |option, opt_index| %>
                  <li class="<%= 'is-correct' if option.correct? %>"<%= ' data-correct="true"'.html_safe if option.correct? %>><%= option_letter(opt_index) %>. <%= option.body %><% if option.correct? %><span class="visually-hidden"> (correct)</span><% end %></li>
                <% end %>
              </ul>
            </div>

            <div class="question-item__actions">
              <div class="buttons">
                <%= button_to move_up_moderate_quiz_question_path(@quiz, question),
                      method: :patch,
                      disabled: index == 0,
                      class: "btn btn--ghost btn--icon",
                      aria: { label: "Move up" },
                      title: "Move up",
                      form: { data: { turbo: false } } do %>
                  <span aria-hidden="true">↑</span>
                <% end %>
                <%= button_to move_down_moderate_quiz_question_path(@quiz, question),
                      method: :patch,
                      disabled: index == total_count - 1,
                      class: "btn btn--ghost btn--icon",
                      aria: { label: "Move down" },
                      title: "Move down",
                      form: { data: { turbo: false } } do %>
                  <span aria-hidden="true">↓</span>
                <% end %>
              </div>

              <%= form_with url: toggle_active_moderate_quiz_question_path(@quiz, question),
                    method: :patch,
                    class: "inline-form",
                    data: { turbo: false } do %>
                <label class="checkbox">
                  <input type="hidden" name="question[active]" value="0">
                  <input type="checkbox"
                         name="question[active]"
                         value="1"
                         <%= "checked" if question.active? %>
                         data-action="change->question-active#toggle">
                  Active
                </label>
              <% end %>

              <div class="buttons">
                <%= link_to "Edit", edit_moderate_quiz_question_path(@quiz, question), class: "btn btn--sm" %>
                <%= button_to "Delete",
                      moderate_quiz_question_path(@quiz, question),
                      method: :delete,
                      class: "btn btn--sm btn--danger",
                      form: { data: { turbo: false }, onsubmit: "return confirm('Delete this question?')" } %>
              </div>
            </div>
          </li>
        <% end %>
      </ol>
    <% else %>
      <div class="empty">
        No questions yet. Add your first question to build this quiz.
      </div>
    <% end %>
  </section>
</div>
