import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["list", "row", "template"]

  add() {
    const index = this.rowTargets.length
    const num = index + 1
    const html = this.templateTarget.innerHTML
      .replaceAll("__INDEX__", String(index))
      .replaceAll("__NUM__", String(num))

    this.listTarget.insertAdjacentHTML("beforeend", html)
    const newRow = this.rowTargets[this.rowTargets.length - 1]
    const input = newRow?.querySelector("[data-role='body-input']")
    if (input) input.focus()
  }

  remove(event) {
    const row = event.currentTarget.closest("[data-option-rows-target='row']")
    if (!row) return

    row.remove()
    this.renumber()
  }

  toggleCheckbox(event) {
    const wrapper = event.currentTarget.closest(".checkbox")
    const checkbox = wrapper?.querySelector("input[type='checkbox']")
    if (checkbox) {
      checkbox.checked = !checkbox.checked
      checkbox.dispatchEvent(new Event("change", { bubbles: true }))
    }
  }

  renumber() {
    this.rowTargets.forEach((row, index) => {
      const num = index + 1
      const idInput = row.querySelector("[data-role='id']")
      const bodyLabel = row.querySelector("[data-role='body-label']")
      const bodyInput = row.querySelector("[data-role='body-input']")
      const correctHidden = row.querySelector("[data-role='correct-hidden']")
      const correctLabel = row.querySelector("[data-role='correct-label']")
      const correctInput = row.querySelector("[data-role='correct-input']")
      const removeButton = row.querySelector("[data-role='remove-button']")

      if (idInput) idInput.name = `question[option_rows][${index}][id]`

      if (bodyLabel) {
        bodyLabel.setAttribute("for", `question_option_${num}_body`)
        bodyLabel.textContent = `Option ${num}`
      }
      if (bodyInput) {
        bodyInput.id = `question_option_${num}_body`
        bodyInput.name = `question[option_rows][${index}][body]`
        bodyInput.placeholder = `Option ${num}`
        bodyInput.setAttribute("aria-label", `Option ${num}`)
      }

      if (correctHidden) correctHidden.name = `question[option_rows][${index}][correct]`
      if (correctLabel) {
        correctLabel.setAttribute("for", `question_option_${num}_correct`)
        correctLabel.textContent = `Option ${num} is correct`
      }
      if (correctInput) {
        correctInput.id = `question_option_${num}_correct`
        correctInput.name = `question[option_rows][${index}][correct]`
        correctInput.setAttribute("aria-label", `Option ${num} is correct`)
      }

      if (removeButton) {
        removeButton.setAttribute("aria-label", `Remove option ${num}`)
        removeButton.setAttribute("title", `Remove option ${num}`)
      }
    })
  }
}
