import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static values = { source: String }

  disconnect() {
    if (this.resetTimer) clearTimeout(this.resetTimer)
  }

  async copy() {
    const sourceEl = document.getElementById(this.sourceValue)
    if (!sourceEl) return

    const text = sourceEl.textContent || ""
    let copied = false

    if (navigator.clipboard && window.isSecureContext) {
      try {
        await navigator.clipboard.writeText(text)
        copied = true
      } catch {
        copied = false
      }
    }

    if (!copied) {
      copied = this.fallbackCopy(text)
    }

    if (copied) {
      this.showFeedback()
    }
  }

  fallbackCopy(text) {
    const textarea = document.createElement("textarea")
    textarea.value = text
    textarea.setAttribute("readonly", "")
    textarea.style.position = "fixed"
    textarea.style.opacity = "0"
    document.body.appendChild(textarea)
    textarea.select()

    let ok = false
    try {
      ok = document.execCommand("copy")
    } catch {
      ok = false
    } finally {
      textarea.remove()
    }
    return ok
  }

  showFeedback() {
    const original = this.originalLabel || this.element.textContent
    this.originalLabel = original
    this.element.textContent = "Copied!"

    if (this.resetTimer) clearTimeout(this.resetTimer)
    this.resetTimer = setTimeout(() => {
      this.element.textContent = this.originalLabel
    }, 2000)
  }
}
